#!/usr/bin/env python3
"""A source category now follows the SOP Xtrium attached, automatically. Run from the repo root. Safe to run twice. Any file that is replaced is first copied
to ~/xtrium_backup_45/ (outside the repo)."""
import os, sys, zlib, base64, shutil, hashlib
sys.stdout.reconfigure(errors='replace')
DATA = {"backend/app/services/sop_requirements.py": "", "backend/app/api/v1/routes/quality.py": ""}
bk = os.path.expanduser("~/xtrium_backup_45")
n = 0
for path, b in DATA.items():
    new = zlib.decompress(base64.b64decode(b))
    if os.path.exists(path):
        old = open(path, 'rb').read()
        crlf = b'\r\n' in old
        if old.replace(b'\r\n', b'\n') == new:
            print("same     ", path); continue
        os.makedirs(os.path.dirname(os.path.join(bk, path)), exist_ok=True)
        shutil.copy2(path, os.path.join(bk, path))
        verb = "replaced "
    else:
        crlf = False; verb = "created  "
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    out = new.replace(b'\n', b'\r\n') if crlf else new
    open(path, 'wb').write(out)
    print(verb, path); n += 1

# integrations.py is large and shared with other rounds, so it gets one small anchored edit instead of a whole-file replace.
ip = "backend/app/api/v1/routes/integrations.py"
if os.path.exists(ip):
    raw = open(ip, 'rb').read().decode('utf-8'); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n')
    mark = "_sr.follow_category(source)"
    anchor = "    got = await _load_sop(source, db, force=True)\n    return {\n        \"source_id\": source.id,"
    if mark in t: print("same      ", ip)
    elif anchor in t:
        t = t.replace(anchor, "    got = await _load_sop(source, db, force=True)\n    from app.services import sop_requirements as _sr\n    _sr.follow_category(source)\n    return {\n        \"source_id\": source.id,", 1)
        open(ip, 'wb').write((t.replace('\n', '\r\n') if crlf else t).encode('utf-8')); print("edited    ", ip)
    else: print("NO MATCH  ", ip, "(not needed: the other two files already do the update on every screen load)")
print()
print(n, "file(s) updated." + (" Backups are in " + bk if n else ""))
